                sum += alpha * l_A[i][k] * l_B[k][j];
            }
            l_tmp[i][j] = sum;
        }
    }

    // Compute D = beta * D + tmp * C
    for (int i = 0; i < NI; i++) {
        for (int j = 0; j < NL; j++) {
#pragma HLS PIPELINE II=1
            double sum = l_D[i][j] * beta;
            for (int k = 0; k < NJ; k++) {
#pragma HLS UNROLL factor=8
                sum += l_tmp[i][k] * l_C[k][j];
            }
            l_D[i][j] = sum;
        }
    }

    // Write back tmp
    for (int i = 0; i < NI; i++)
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
