#include "3mm.h"

extern "C" {

void kernel_3mm(
		double E[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double F[ NJ + 0][NL + 0],
		double C[ NJ + 0][NM + 0],
		double D[ NM + 0][NL + 0],
		double G[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=E offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=F offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=G offset=slave bundle=gmem6
#pragma HLS INTERFACE s_axilite port=E bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=F bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=G bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers for intermediate results to enable partitioning
    static double E_local[NI][NJ];
    static double F_local[NJ][NL];

#pragma HLS ARRAY_PARTITION variable=E_local cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=F_local cyclic factor=8 dim=2

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;
    const int nm = NM;

    int i, j, k;

    // Compute E = A * B
    for (i = 0; i < ni; i++) {
        for (j = 0; j < nj; j++) {
            E_local[i][j] = 0.0;
        }
    }

    for (i = 0; i < ni; i++) {
        for (j = 0; j < nj; j++) {
            double sum = 0.0;
            for (k = 0; k < nk; ++k) {
#pragma HLS PIPELINE II=1
                sum += A[i][k] * B[k][j];
            }
            E_local[i][j] = sum;
        }
    }

    // Write E back to global memory
    for (i = 0; i < ni; i++) {
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            E[i][j] = E_local[i][j];
        }
    }

    // Compute F = C * D
    for (i = 0; i < nj; i++) {
        for (j = 0; j < nl; j++) {
            F_local[i][j] = 0.0;
        }
    }

    for (i = 0; i < nj; i++) {
        for (j = 0; j < nl; j++) {
            double sum = 0.0;
            for (k = 0; k < nm; ++k) {
#pragma HLS PIPELINE II=1
                sum += C[i][k] * D[k][j];
            }
            F_local[i][j] = sum;
        }
    }

    // Write F back to global memory
    for (i = 0; i < nj; i++) {
        for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
            F[i][j] = F_local[i][j];
        }
    }

    // Compute G = E * F
    for (i = 0; i < ni; i++) {
        for (j = 0; j < nl; j++) {
            double sum = 0.0;
            for (k = 0; k < nj; ++k) {
#pragma HLS PIPELINE II=1
                sum += E_local[i][k] * F_local[k][j];
            }
            G[i][j] = sum;
        }
    }
}

} // extern "C"

#include "3mm.h"

extern "C" {

void kernel_3mm(    
		double E[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double F[ NJ + 0][NL + 0],
		double C[ NJ + 0][NM + 0],
		double D[ NM + 0][NL + 0],
		double G[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=E offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=F offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=G offset=slave bundle=gmem6
#pragma HLS INTERFACE s_axilite port=E bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=F bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=G bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;
    const int nm = NM;

    // Local buffers for better memory access patterns
    double E_local[NI][NJ];
    double A_local[NI][NK];
    double B_local[NK][NJ];
    double F_local[NJ][NL];
    double C_local[NJ][NM];
    double D_local[NM][NL];
    double G_local[NI][NL];

#pragma HLS ARRAY_PARTITION variable=E_local cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=B_local cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=F_local cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=C_local cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=D_local cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=G_local cyclic factor=8 dim=2

    // Load A
    load_A: for (int i = 0; i < ni; i++)
        for (int j = 0; j < nk; j++) {
#pragma HLS PIPELINE II=1
            A_local[i][j] = A[i][j];
        }

    // Load B
    load_B: for (int i = 0; i < nk; i++)
        for (int j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            B_local[i][j] = B[i][j];
        }

    // Load C
    load_C: for (int i = 0; i < nj; i++)
        for (int j = 0; j < nm; j++) {
#pragma HLS PIPELINE II=1
            C_local[i][j] = C[i][j];
        }

    // Load D
    load_D: for (int i = 0; i < nm; i++)
        for (int j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
            D_local[i][j] = D[i][j];
        }

    int i, j, k;

    // E = A * B
    loop_E_i: for (i = 0; i < ni; i++) {
        loop_E_j: for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            double sum = 0.0;
            loop_E_k: for (k = 0; k < nk; ++k) {
#pragma HLS UNROLL factor=4
                sum += A_local[i][k] * B_local[k][j];
            }
            E_local[i][j] = sum;
        }
    }

    // F = C * D
    loop_F_i: for (i = 0; i < nj; i++) {
        loop_F_j: for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
            double sum = 0.0;
            loop_F_k: for (k = 0; k < nm; ++k) {
#pragma HLS UNROLL factor=4
                sum += C_local[i][k] * D_local[k][j];
            }
            F_local[i][j] = sum;
        }
    }

    // G = E * F
    loop_G_i: for (i = 0; i < ni; i++) {
        loop_G_j: for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
            double sum = 0.0;
            loop_G_k: for (k = 0; k < nj; ++k) {
#pragma HLS UNROLL factor=4
                sum += E_local[i][k] * F_local[k][j];
            }
            G_local[i][j] = sum;
        }
    }

    // Write back E
    store_E: for (int i = 0; i < ni; i++)
        for (int j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            E[i][j] = E_local[i][j];
        }

    // Write back F
    store_F: for (int i = 0; i < nj; i++)
        for (int j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
            F[i][j] = F_local[i][j];
        }

    // Write back G
    store_G: for (int i = 0; i < ni; i++)
        for (int j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
            G[i][j] = G_local[i][j];
        }
}

} // extern "C"

#include "atax.h"

extern "C" {

void kernel_atax(
        double A[M + 0][N + 0],
        double x[N + 0],
        double y[N + 0],
        double tmp[M + 0])
{
    #pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem
    #pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem
    #pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem
    #pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem
    #pragma HLS INTERFACE s_axilite port=A      bundle=control
    #pragma HLS INTERFACE s_axilite port=x      bundle=control
    #pragma HLS INTERFACE s_axilite port=y      bundle=control
    #pragma HLS INTERFACE s_axilite port=tmp    bundle=control
    #pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers to avoid repeated global memory traffic
    double l_A[M][N];
    double l_x[N];
    double l_y[N];
    double l_tmp[M];

    #pragma HLS ARRAY_PARTITION variable=l_A   cyclic factor=8 dim=2
    #pragma HLS ARRAY_PARTITION variable=l_x   cyclic factor=8 dim=1
    #pragma HLS ARRAY_PARTITION variable=l_y   cyclic factor=8 dim=1
    #pragma HLS ARRAY_PARTITION variable=l_tmp complete dim=1

    // Load x from global memory
    load_x: for (int j = 0; j < N; j++) {
        #pragma HLS PIPELINE II=1
        l_x[j] = x[j];
    }

    // Load A from global memory
    load_A: for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            #pragma HLS PIPELINE II=1
            l_A[i][j] = A[i][j];
        }
    }

    // Initialize y
    init_y: for (int i = 0; i < N; i++) {
        #pragma HLS PIPELINE II=1
        l_y[i] = 0.0;
    }

    // Main computation
    outer: for (int i = 0; i < M; i++) {
        double tmp_i = 0.0;

        // Compute tmp[i] = sum_j A[i][j] * x[j]
        inner1: for (int j = 0; j < N; j++) {
            #pragma HLS PIPELINE II=1
            #pragma HLS UNROLL factor=8
            tmp_i += l_A[i][j] * l_x[j];
        }
        l_tmp[i] = tmp_i;

        // Accumulate y[j] += A[i][j] * tmp[i]
        inner2: for (int j = 0; j < N; j++) {
            #pragma HLS PIPELINE II=1
            #pragma HLS UNROLL factor=8
            l_y[j] += l_A[i][j] * tmp_i;
        }
    }

    // Write tmp back to global memory
    store_tmp: for (int i = 0; i < M; i++) {
        #pragma HLS PIPELINE II=1
        tmp[i] = l_tmp[i];
    }

    // Write y back to global memory
    store_y: for (int j = 0; j < N; j++) {
        #pragma HLS PIPELINE II=1
        y[j] = l_y[j];
    }
}

} // extern "C"

#include "atax.h"

extern "C" {

void kernel_atax(
        double A[ M + 0][N + 0],
        double x[ N + 0],
        double y[ N + 0],
        double tmp[ M + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=x      bundle=control
#pragma HLS INTERFACE s_axilite port=y      bundle=control
#pragma HLS INTERFACE s_axilite port=tmp    bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local copies for fast access
    double local_A[M][N];
    double local_x[N];
    double local_y[N];
    double local_tmp[M];

#pragma HLS ARRAY_PARTITION variable=local_A cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=local_x cyclic factor=8
#pragma HLS ARRAY_PARTITION variable=local_y cyclic factor=8
#pragma HLS ARRAY_PARTITION variable=local_tmp complete

    // Load x
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        local_x[j] = x[j];
    }

    // Load A
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            local_A[i][j] = A[i][j];
        }
    }

    // Initialize y
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        local_y[i] = 0.0;
    }

    // Compute tmp and accumulate into y
    for (int i = 0; i < M; i++) {
        double tmp_i = 0.0;

        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
            tmp_i += local_A[i][j] * local_x[j];
        }

        local_tmp[i] = tmp_i;

        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
            local_y[j] += local_A[i][j] * tmp_i;
        }
    }

    // Write back tmp
    for (int i = 0; i < M; i++) {
#pragma HLS PIPELINE II=1
        tmp[i] = local_tmp[i];
    }

    // Write back y
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        y[j] = local_y[j];
    }
}

} // extern "C"

#include "bicg.h"

extern "C" {

void kernel_bicg(
        double A[N + 0][M + 0],
        double s[M + 0],
        double q[N + 0],
        double p[M + 0],
        double r[N + 0])
{
#pragma HLS INTERFACE m_axi port=A      offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=s      offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=q      offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=p      offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=r      offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=s      bundle=control
#pragma HLS INTERFACE s_axilite port=q      bundle=control
#pragma HLS INTERFACE s_axilite port=p      bundle=control
#pragma HLS INTERFACE s_axilite port=r      bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers for parallel access and banking
    double l_s[M];
    double l_q[N];
    double l_p[M];
    double l_r[N];
    double l_A[N][M];

#pragma HLS ARRAY_PARTITION variable=l_s cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_q cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_p cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_r cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_A cyclic factor=8 dim=2

    // Load inputs from global memory
    load_r: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        l_r[i] = r[i];
    }

    load_p: for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
        l_p[j] = p[j];
    }

    load_A: for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
            l_A[i][j] = A[i][j];
        }
    }

    // Initialize s
    init_s: for (int i = 0; i < M; i++) {
#pragma HLS PIPELINE II=1
        l_s[i] = 0.0;
    }

    // Main compute loops
    compute: for (int i = 0; i < N; i++) {
        double q_acc = 0.0;
        double ri = l_r[i];

        inner: for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
            double aij = l_A[i][j];
            l_s[j] = l_s[j] + ri * aij;
            q_acc   = q_acc  + aij * l_p[j];
        }

        l_q[i] = q_acc;
    }

    // Write outputs back to global memory
    store_s: for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
        s[j] = l_s[j];
    }

    store_q: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        q[i] = l_q[i];
    }
}

