extern "C" {

void kernel_gramschmidt(
    double A[M + 0][N + 0],
    double R[N + 0][N + 0],
    double Q[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=R offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=Q offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=R bundle=control
#pragma HLS INTERFACE s_axilite port=Q bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local arrays for better memory access patterns
    double A_local[M][N];
    double R_local[N][N];
    double Q_local[M][N];

#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=R_local cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=Q_local cyclic factor=8 dim=2

    // Copy A to local
    for (int i = 0; i < M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            A_local[i][j] = A[i][j];
        }
    }

    const int m = M;
    const int n = N;

    int i, j, k;
    double nrm;

    for (k = 0; k < n; k++) {
        nrm = 0.0;
        for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
            nrm += A_local[i][k] * A_local[i][k];
        }
        R_local[k][k] = sqrt(nrm);

        for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
            Q_local[i][k] = A_local[i][k] / R_local[k][k];
        }

        for (j = k + 1; j < n; j++) {
            R_local[k][j] = 0.0;
            for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
                R_local[k][j] += Q_local[i][k] * A_local[i][j];
            }
            for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
                A_local[i][j] = A_local[i][j] - Q_local[i][k] * R_local[k][j];
            }
        }
    }

    // Write back results
    for (int i = 0; i < M; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            A[i][j] = A_local[i][j];
            Q[i][j] = Q_local[i][j];
        }
    }

    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) {
            R[i][j] = R_local[i][j];
        }
    }
}

} // extern "C"

#include "jacobi-1d.h"

extern "C" {

void kernel_jacobi_1d(
    double A[N + 0],
    double B[N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int tsteps = TSTEPS;

    // Local buffers to avoid repeated global memory traffic across timesteps
    double lA[N];
    double lB[N];
#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=lB cyclic factor=4 dim=1

    // Load A from global memory into local buffer
    load_A: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        lA[i] = A[i];
    }

    // Load B from global memory into local buffer
    load_B: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        lB[i] = B[i];
    }

    // Main Jacobi iteration - true dependency on t, so cannot pipeline outer loop
    for (int t = 0; t < tsteps; t++) {
        // Update B from A
        update_B: for (int i = 1; i < n - 1; i++) {
#pragma HLS PIPELINE II=1
            lB[i] = 0.33333 * (lA[i-1] + lA[i] + lA[i + 1]);
        }
        // Update A from B
        update_A: for (int i = 1; i < n - 1; i++) {
#pragma HLS PIPELINE II=1
            lA[i] = 0.33333 * (lB[i-1] + lB[i] + lB[i + 1]);
        }
    }

    // Write results back to global memory
    store_A: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        A[i] = lA[i];
    }

    store_B: for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        B[i] = lB[i];
    }
}

