void kernel_ludcmp(
		   double A[ N + 0][N + 0],
		   double b[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0])
{
#pragma HLS ARRAY_PARTITION variable=A cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=b cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=x cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=y cyclic factor=8 dim=1

    const int n = N;

    int i, j, k;
    double w;

    // LU decomposition
    for (i = 0; i < n; i++) {
        for (j = 0; j < i; j++) {
            w = A[i][j];
            for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
                w -= A[i][k] * A[k][j];
            }
            A[i][j] = w / A[j][j];
        }
        for (j = i; j < n; j++) {
            w = A[i][j];
            for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
                w -= A[i][k] * A[k][j];
            }
            A[i][j] = w;
        }
    }

    // Forward substitution: solve L*y = b
    for (i = 0; i < n; i++) {
        w = b[i];
        for (j = 0; j < i; j++) {
#pragma HLS PIPELINE II=1
            w -= A[i][j] * y[j];
        }
        y[i] = w;
    }

    // Backward substitution: solve U*x = y
    for (i = n - 1; i >= 0; i--) {
        w = y[i];
        for (j = i + 1; j < n; j++) {
#pragma HLS PIPELINE II=1
            w -= A[i][j] * x[j];
        }
        x[i] = w / A[i][i];
    }
}

