    // Store C back to global memory
    store_C_i: for (int i = 0; i < m; i++) {
        store_C_j: for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = C_local[i][j];
        }
    }
}

