#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=b_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=L_row  cyclic factor=8 dim=1

    // Load b into local buffer
    load_b: for (int k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
        b_local[k] = b[k];
    }

    // Initialize x_local from b_local
    init_x: for (int k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
        x_local[k] = b_local[k];
    }

    // Main triangular solve loop
    // Outer loop has loop-carried dependency: x[i] depends on x[j<i]
    // Cannot pipeline outer loop; pipeline inner loop instead
    outer: for (int i = 0; i < n; i++) {

        // Load row i of L into local buffer
        load_row: for (int k = 0; k <= i; k++) {
#pragma HLS PIPELINE II=1
            L_row[k] = L[i][k];
        }

        // Inner loop: accumulate dot product L[i][0..i-1] * x[0..i-1]
        // This loop is free of loop-carried dependencies within the same i
        double acc = 0.0;
        inner: for (int j = 0; j < i; j++) {
#pragma HLS PIPELINE II=1
            acc += L_row[j] * x_local[j];
        }

        // Update x[i]
        x_local[i] = (x_local[i] - acc) / L_row[i];
    }

    // Write x_local back to global memory
    store_x: for (int k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
        x[k] = x_local[k];
    }
}

} // extern "C"

#include "trisolv.h"

extern "C" {

void kernel_trisolv(
		    double L[ N + 0][N + 0],
		    double x[ N + 0],
		    double b[ N + 0])
{
#pragma HLS INTERFACE m_axi port=L offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=L bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=b bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    double x_local[N];
    double b_local[N];
    double L_local[N][N];

#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=L_local cyclic factor=8 dim=2

    // Load b into local buffer
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        b_local[i] = b[i];
    }

    // Load L into local buffer
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            L_local[i][j] = L[i][j];
        }
    }

    const int n = N;
    int i, j;

    for (i = 0; i < n; i++) {
        x_local[i] = b_local[i];
        for (j = 0; j < i; j++) {
#pragma HLS PIPELINE II=1
            x_local[i] -= L_local[i][j] * x_local[j];
        }
        x_local[i] = x_local[i] / L_local[i][i];
    }

    // Write results back
    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        x[i] = x_local[i];
    }
}

} // extern "C"

#include "trmm.h"

extern "C" {

void kernel_trmm(
        double alpha,
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0 depth=3600
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1 depth=4800
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers to avoid repeated global memory access and enable partitioning
    double A_local[M][M];
    double B_local[M][N];

#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=B_local cyclic factor=8 dim=2

    // Load A into local buffer
    load_A_outer: for (int i = 0; i < M; i++) {
        load_A_inner: for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
            A_local[i][j] = A[i][j];
        }
    }

    // Load B into local buffer
    load_B_outer: for (int i = 0; i < M; i++) {
        load_B_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            B_local[i][j] = B[i][j];
        }
    }

    // Compute: preserve original algorithm exactly
    const int m = M;
    const int n = N;

    int i, j, k;
    for (i = 0; i < m; i++) {
        for (j = 0; j < n; j++) {
            double b_val = B_local[i][j];
            for (k = i + 1; k < m; k++) {
#pragma HLS PIPELINE II=1
                b_val += A_local[k][i] * B_local[k][j];
            }
            B_local[i][j] = alpha * b_val;
        }
    }

    // Store B back to global memory
    store_B_outer: for (int i = 0; i < M; i++) {
        store_B_inner: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            B[i][j] = B_local[i][j];
        }
    }
}

} // extern "C"

#include "trmm.h"

extern "C" {

void kernel_trmm(
        double alpha,
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers for HBM-friendly access patterns
    double A_local[M][M];
    double B_local[M][N];

#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=B_local cyclic factor=4 dim=2

    // Load A into local buffer
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
            A_local[i][j] = A[i][j];
        }
    }

    // Load B into local buffer
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            B_local[i][j] = B[i][j];
        }
    }

    const int m = M;
    const int n = N;

    int i, j, k;
    for (i = 0; i < m; i++) {
        for (j = 0; j < n; j++) {
            for (k = i + 1; k < m; k++) {
#pragma HLS PIPELINE II=1
                B_local[i][j] += A_local[k][i] * B_local[k][j];
            }
            B_local[i][j] = alpha * B_local[i][j];
        }
    }

    // Write back B
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            B[i][j] = B_local[i][j];
        }
    }
}

} // extern "C"
